class Solution { public int largest1BorderedSquare(int[][] grid){int rows=grid.length,columns=grid[0].length,best=0;int[][] left=new int[rows][columns],up=new int[rows][columns];for(int r=0;r<rows;r++)for(int c=0;c<columns;c++)if(grid[r][c]==1){left[r][c]=1+(c>0?left[r][c-1]:0);up[r][c]=1+(r>0?up[r-1][c]:0);for(int side=Math.min(left[r][c],up[r][c]);side>best;side--)if(left[r-side+1][c]>=side&&up[r][c-side+1]>=side){best=side;break;}}return best*best;} }
